steps.script:
for uid in GameState.state["units"]:
	var u = GameState.state["units"][uid]
	if int(u.get("owner", 0)) == 1:
		for m in u.get("models", []):
			if m.get("position") != null:
				m["position"] = {"x": 880.0, "y": 1200.0}
return true

for store in [GameState.state, PhaseManager.get_current_phase_instance().game_state_snapshot]:
	var u = store["units"]["U_STRIKE_FORCE_A"]
	u.merge({"status": 7, "reserve_type": "strategic_reserves"}, true)
	u["flags"] = {"in_reserves": true}
	u["meta"]["abilities"] = []
	for m in u["models"]:
		m["position"] = null
	store["meta"]["battle_round"] = 2
return GameState.get_battle_round()

var list = tree.current_scene.movement_controller.unit_list
for i in range(list.item_count):
	if str(list.get_item_metadata(i)) == "U_STRIKE_FORCE_A":
		return i
return -1

tree.current_scene.deployment_controller.reset_unit()
for store in [GameState.state, PhaseManager.get_current_phase_instance().game_state_snapshot]:
	var u = store["units"]["U_STRIKE_FORCE_A"]
	u["status"] = 7
	u["flags"] = {"in_reserves": true}
	for m in u["models"]:
		m["position"] = null
return int(GameState.state["units"]["U_STRIKE_FORCE_A"]["status"])
